effect.shader:
vec3 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat9;
float u_xlat12;
bvec2 u_xlatb12;
vec2 u_xlat14;
bvec2 u_xlatb14;
float u_xlat18;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat12 = _direction * -0.0174532942;
    u_xlat1.x = sin(u_xlat12);
    u_xlat2.x = cos(u_xlat12);
    u_xlat3.x = sin((-u_xlat12));
    u_xlat3.y = u_xlat2.x;
    u_xlat2.x = dot(u_xlat3.yx, u_xlat0.xy);
    u_xlat3.z = u_xlat1.x;
    u_xlat2.y = dot(u_xlat3.zy, u_xlat0.xy);
    u_xlat0.xy = u_xlat2.xy * _scale.xy + vec2(0.5, 0.5);
    u_xlat0.xyz = texture(texture0, u_xlat0.xy).xyz;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat2 = u_xlat0.xxzz * vec4(0.0500000007, 0.0500000007, 0.0500000007, 0.0500000007) + acScreenNorm.xyxy;
    u_xlat12 = dot(u_xlat2.xy, vec2(92.0, 80.0));
    u_xlat18 = dot(u_xlat2.xy, vec2(41.0, 62.0));
    u_xlat12 = sin(u_xlat12);
    u_xlat18 = cos(u_xlat18);
    u_xlat12 = u_xlat18 * 51.0 + u_xlat12;
    u_xlat2.x = fract(u_xlat12);
    u_xlat12 = dot(u_xlat2.zw, vec2(92.0, 80.0));
    u_xlat18 = dot(u_xlat2.zw, vec2(41.0, 62.0));
    u_xlat12 = sin(u_xlat12);
    u_xlat18 = cos(u_xlat18);
    u_xlat12 = u_xlat18 * 51.0 + u_xlat12;
    u_xlat2.y = fract(u_xlat12);
    u_xlat0.xy = u_xlat0.xy * vec2(_strength);
    u_xlat0.xy = u_xlat2.xy * u_xlat0.xy;
    u_xlat0.z = _direction + 125.0;
    u_xlat0.xyz = u_xlat0.xyz * vec3(0.100000001, 0.100000001, 0.0174532942);
    u_xlat2.x = sin(u_xlat0.z);
    u_xlat3.x = cos(u_xlat0.z);
    u_xlat4.x = sin((-u_xlat0.z));
    u_xlat4.y = u_xlat3.x;
    u_xlat3.x = dot(u_xlat4.yx, u_xlat0.xy);
    u_xlat4.z = u_xlat2.x;
    u_xlat3.y = dot(u_xlat4.zy, u_xlat0.xy);
    u_xlat0.xy = u_xlat3.xy + acScreenNorm.xy;
    u_xlatb12.x = int(_keep_edge)==1;
    u_xlatb2.xy = lessThan(u_xlat0.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb14.xy = lessThan(vec4(1.0, 1.0, 1.0, 1.0), u_xlat0.xyxy).xy;
    u_xlat9.xy = fract(u_xlat0.xy);
    u_xlat9.xy = (-u_xlat9.xy) + vec2(1.0, 1.0);
    u_xlat14.x = (u_xlatb14.x) ? u_xlat9.x : u_xlat0.x;
    u_xlat14.y = (u_xlatb14.y) ? u_xlat9.y : u_xlat0.y;
    u_xlat2.x = (u_xlatb2.x) ? (-u_xlat0.x) : u_xlat14.x;
    u_xlat2.y = (u_xlatb2.y) ? (-u_xlat0.y) : u_xlat14.y;
    u_xlat0.xy = (u_xlatb12.x) ? u_xlat2.xy : u_xlat0.xy;
    u_xlat2 = texture(inputImg, u_xlat0.xy);
    u_xlat12 = abs(u_xlat3.x) * _colorize;
    u_xlat3.xyz = (-u_xlat2.xyz) + _color.xyz;
    u_xlat3.w = u_xlat1.w + (-u_xlat2.w);
    u_xlat2 = vec4(u_xlat12) * u_xlat3 + u_xlat2;
    if(int(_use_inner_mask) != 0) {
        u_xlatb12.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_b_clip_mask)), ivec4(1, 1, 1, 1)).xy;
        u_xlat3 = (u_xlatb12.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat2;
        u_xlat4 = texture(Mask, u_xlat0.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat0.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb12.y) ? u_xlat0.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat2;
    }
    return;
}
